大东：只要这只小熊猫出现在了你的屏幕上，你的电脑基本就算玩完了。蓝屏、频繁重启、数据被删、彻底死机……
小白：这个“熊猫烧香”是不是出自某个神秘组织，或者某位黑客大神之手呢？
