大东：是的，但原病毒只会对EXE图标进行替换，并不会对系统本身进行破坏。而大多数病毒是中等病毒变种，用户电脑中毒后可能会出现蓝屏、频繁重启以及系统硬盘中数据文件被破坏等现象。
