大东：城市SOC功能：全网监测——覆盖城市关键基础设施；威胁分析——识别针对城市的攻击；事件响应——协调各部门处置；情报共享——与国家和区域中心联动；预警发布——向公众发布安全预警；演练培训——提升整体安全能力。
