const ARTICLE_115 = `一、小白剧场

小白：东哥，什么是量子密码学？
大东：量子密码学利用量子力学原理实现信息安全，最成熟的是量子密钥分发(QKD)。基于量子不可克隆定理和测量坍缩原理，理论上可以提供无条件安全的密钥分发。
小白：量子密钥分发怎么工作？
大东：QKD工作原理：发送方用不同偏振态编码密钥比特；接收方随机选择测量基测量；双方公开比对测量基（不泄露密钥）；保留基相同的数据作为密钥；任何窃听都会引入错误被检测；BB84协议是最著名的QKD协议。
小白：量子密码与传统加密有什么区别？
大东：关键区别：传统加密基于计算复杂性假设（如大数分解困难）；量子密码基于物理定律，理论上不可破解；QKD只解决密钥分发问题，不直接加密数据；需要结合一次性密码本或对称加密使用；目前主要用于高安全需求场景。

二、大话始末

小白：东哥，QKD有哪些技术实现？
大东：QKD技术路线：离散变量QKD——用单光子偏振或相位编码；连续变量QKD——用光场的正交分量编码；测量设备无关QKD——消除探测器漏洞；双场QKD——突破距离限制；自由空间QKD——卫星量子通信；目前商用系统主要是离散变量方案。
小白：量子密码面临哪些挑战？
大东：技术挑战：距离限制——光纤衰减限制传输距离（约100-400公里）；速率限制——密钥生成速率较低；设备漏洞——实际设备偏离理论假设；成本高昂——设备价格昂贵；网络集成——与现有网络融合；需要量子中继器突破距离限制。
小白：中国在量子通信领域有什么成就？
大东：中国成就：2016年发射"墨子号"量子科学实验卫星；建成"京沪干线"2000公里光纤量子通信骨干网；实现洲际量子通信；多次刷新QKD传输距离世界纪录；推动QKD标准化和产业化；在量子通信领域处于国际领先地位。
小白：量子密码有哪些应用场景？
大东：应用场景：政务通信——高保密级别通信保护；金融交易——保护交易数据；电力系统——保护调度指令；国防军事——最高级别安全通信；数据中心互联——保护跨中心数据传输；关键基础设施——保护控制指令。
小白：量子密码标准化进展？
大东：标准化进展：ITU-T制定QKD网络标准；ETSI发布QKD安全证明指南；中国密码行业标准GM/T；ISO/IEC JTC 1/SC 27研究QKD安全评估；CCRC开展QKD产品认证；标准化推动产业化发展。
小白：量子密码与后量子密码有什么关系？
大东：两者关系：量子密码利用量子力学保护通信；后量子密码是抵抗量子计算机攻击的经典算法；两者互补——QKD解决密钥分发，后量子算法解决加密和签名；未来可能结合使用——QKD分发后量子算法的密钥；共同构建量子时代的安全体系。
小白：量子密码是信息安全的前沿领域！
大东：没错，量子密码代表了密码学的未来方向，虽然还有技术挑战，但前景广阔。小白，关注量子技术发展是面向未来的投资！

来源：中国科学院信息工程研究所`;

const ARTICLE_116 = `一、小白剧场

小白：东哥，什么是后量子密码？
大东：后量子密码(Post-Quantum Cryptography, PQC)是能够抵抗量子计算机攻击的经典密码算法。量子计算机能破解RSA、ECC等基于整数分解和离散对数的算法，需要新的密码方案。
小白：量子计算机为什么能破解现有加密？
大东：Shor算法：量子计算机可以在多项式时间内分解大整数和求解离散对数；RSA、Diffie-Hellman、ECC等主流算法都依赖这些难题；Grover算法将暴力搜索加速平方倍，对称密钥长度需加倍；现有加密体系面临根本性威胁。
小白：后量子密码有哪些技术方向？
大东：PQC技术路线：基于格的密码——最短向量问题困难；基于编码的密码——纠错码解码困难；基于多变量的密码——求解多元方程组困难；基于哈希的签名——哈希函数安全性；基于同构的密码——超奇异椭圆曲线同源；各路线有不同优劣。

二、大话始末

小白：东哥，NIST后量子密码标准化进展如何？
大东：NIST标准化：2016年启动全球征集；2022年7月公布首批标准算法：CRYSTALS-Kyber（密钥封装）、CRYSTALS-Dilithium（数字签名）、FALCON（签名）、SPHINCS+（签名）；2023年8月公布附加数字签名算法；标准预计2024年发布。
小白：后量子密码迁移面临什么挑战？
大东：迁移挑战：算法效率——PQC算法通常更大更慢；协议兼容性——需要更新TLS等协议；证书体系——根证书和中间件更新；遗留系统——老旧设备难以更新；混合部署——过渡期的安全策略；互操作性——多厂商协调；测试验证——确保实现正确。
小白：中国在后量子密码方面有什么布局？
大东：中国布局：国家密码管理局组织PQC研究；商密算法SM2、SM9向PQC扩展；参与国际标准制定；自主研发PQC算法；开展迁移研究；培养专业人才；量子计算和PQC同步发展；确保密码自主可控。
小白：企业如何准备后量子密码迁移？
大东：迁移准备：密码清单——盘点使用的密码算法；风险评估——评估量子威胁时间线；制定路线图——分阶段迁移计划；测试环境——建立PQC测试平台；供应商沟通——确保产品支持PQC；员工培训——提升PQC认知；关注标准——跟踪NIST等标准进展。
小白："先收集，后解密"威胁是什么？
大东：Harvest Now, Decrypt Later：攻击者现在收集加密数据存储；等待量子计算机成熟后解密；对长期敏感数据威胁巨大；国家机密、商业秘密、个人隐私；需要立即采取行动保护高价值长期数据；推动PQC提前部署。
小白：后量子密码与现有系统如何共存？
大东：共存策略：混合模式——同时使用经典和PQC算法；敏捷加密——支持算法快速切换；分层保护——不同数据用不同算法；风险评估——根据敏感度选择策略；渐进迁移——优先保护高价值数据；持续监控——跟踪量子计算进展。
小白：后量子密码是应对量子威胁的必由之路！
大东：没错，量子计算的发展不可逆转，密码迁移是长期而复杂的工程。小白，了解后量子密码是密码学学习的重要内容！

来源：中国科学院信息工程研究所`;

const ARTICLE_117 = `一、小白剧场

小白：东哥，空间网络安全是什么？
大东：空间网络安全是保护卫星、空间站、地面站等空间系统免受网络攻击的领域。随着卫星互联网（如Starlink）、卫星导航、遥感等应用普及，空间网络安全越来越重要。
小白：卫星系统面临哪些网络威胁？
大东：卫星威胁：地面站入侵——攻击卫星控制中心；通信链路攻击——截获或干扰卫星通信；供应链攻击——在制造阶段植入后门；固件漏洞——卫星软件漏洞被利用；激光攻击——干扰光学载荷；物理破坏——反卫星武器；轨道劫持——控制卫星机动。
小白：卫星互联网有什么安全风险？
大东：卫星互联网风险：用户终端安全——大量终端成为攻击面；星间链路安全——卫星间通信被窃听；地面网关安全——连接互联网的节点；星座管理安全——控制整个星座的系统；服务可用性——干扰导致服务中断；数据隐私——用户通信被监控。

二、大话始末

小白：东哥，如何保护卫星通信安全？
大东：卫星通信保护：链路加密——上行下行通信加密；认证机制——防止未授权接入；跳频技术——抗干扰；星上处理——减少地面暴露；安全协议——专用卫星通信协议；物理安全——地面站防护；供应链安全——确保组件可信。
小白：GPS等导航系统安全吗？
大东：导航安全挑战：信号欺骗——发送虚假GPS信号；信号干扰——阻断GPS接收； meaconing——记录并重放GPS信号；星历攻击——篡改卫星轨道数据；需要多源导航——结合惯性导航、地面信标；抗干扰接收机——提高信号鉴别能力；备份系统——不依赖单一导航源。
小白：空间网络安全有什么特殊之处？
大东：空间安全特点：物理不可及——卫星在轨难以物理维护；资源受限——星上计算和存储有限；长寿命——15-20年在轨难以更新；恶劣环境——辐射影响电子设备；全球覆盖——攻击可来自任何地方；国际属性——涉及多国法律和管辖。
小白：什么是反卫星武器(ASAT)？
大东：ASAT威胁：动能武器——直接撞击摧毁卫星；共轨武器——在轨接近后攻击；定向能武器——激光或微波破坏；网络攻击——通过地面系统控制卫星；电子战——干扰卫星通信；太空碎片——碰撞产生连锁反应；威胁太空安全和可持续性。
小白：空间网络安全国际合作？
大东：国际合作：联合国和平利用外层空间委员会；外层空间条约和责任公约；欧盟空间监视和跟踪计划；美国太空军和网络司令部；各国空间态势感知共享；商业卫星运营商协作；需要建立空间行为规范。
小白：商业航天时代的安全挑战？
大东：商业航天挑战：大量小卫星——管理复杂度增加；快速部署——安全测试时间不足；COTS组件——商业组件安全风险；频谱竞争——干扰风险；空间碎片——碰撞和连锁反应；责任界定——商业和国家责任模糊；需要新的安全治理模式。
小白：空间网络安全是国家安全的新疆域！
大东：没错，太空已成为关键基础设施，空间网络安全关系到通信、导航、遥感等命脉。小白，关注空间安全是面向太空时代的重要认知！

来源：中国科学院信息工程研究所`;

const ARTICLE_118 = `一、小白剧场

小白：东哥，生物识别安全是什么？
大东：生物识别利用人体固有特征（指纹、人脸、虹膜、声纹、静脉等）进行身份认证。生物识别安全是保护这些生物特征数据，确保识别系统可靠，防止欺骗攻击。
小白：生物识别相比密码有什么优缺点？
大东：优点：方便——无需记忆；唯一——难以共享；持久——不会忘记。缺点：不可撤销——生物特征泄露无法更换；隐私敏感——涉及个人敏感信息；可被采集——在不知情情况下被获取；错误率——存在误识和拒识；需要活体检测防欺骗。
小白：生物识别面临哪些攻击？
大东：生物识别攻击：物理欺骗——假指纹、照片、面具；数字攻击——篡改识别算法或数据库；重放攻击——重放采集的生物特征；侧信道攻击——通过功耗等推断特征；对抗样本——欺骗深度学习识别系统；数据库泄露——生物特征模板被盗。

二、大话始末

小白：东哥，如何保护生物特征数据？
大东：数据保护策略：模板保护——不可逆变换，无法还原原始特征；取消生物特征——可撤销的生物识别；本地处理——特征提取和比对在设备端；加密存储——模板加密保存；最小化采集——只采集必要特征；访问控制——严格限制模板访问；定期更新——支持模板更新。
小白：什么是活体检测？
大东：活体检测技术：动作配合——眨眼、摇头等；纹理分析——皮肤纹理细节；多光谱——可见光+红外；3D结构光——深度信息；血流检测——皮下血液流动；挑战响应——响应随机挑战；AI检测——深度学习识别伪造；多层防护提高安全性。
小白：不同生物特征的安全性如何？
大东：特征安全性：虹膜——误识率最低，难以伪造；指纹——最普及，但容易被复制；人脸——方便但易受照片/视频攻击；声纹——易受录音攻击；静脉——体内特征，难以复制；步态——远距离识别但精度较低；多模态融合——结合多种特征提高安全性。
小白：生物识别标准化和法规？
大东：标准法规：ISO/IEC 30107——活体检测标准；ISO/IEC 19795——生物识别测试标准；GDPR——生物数据是敏感个人数据；中国个人信息保护法——生物识别信息特别保护；等保2.0——生物识别系统安全要求；金融行业标准——支付领域生物识别规范。
小白：AI如何影响生物识别安全？
大东：AI影响：深度伪造——生成逼真假人脸；对抗样本——欺骗深度学习模型；提升识别——深度学习提高准确率；攻击检测——AI检测欺骗攻击；隐私增强——联邦学习保护生物数据；需要攻防同步发展。
小白：生物识别最佳实践？
大东：最佳实践：多因素认证——生物识别+其他因素；分层保护——根据风险选择生物特征；透明告知——明确告知用户数据使用；用户控制——允许用户删除数据；安全审计——定期评估系统安全；应急响应——泄露后的处理预案；隐私设计——隐私保护内置。
小白：生物识别安全是数字身份的关键！
大东：没错，生物识别正在取代密码成为主流认证方式，安全保护至关重要。小白，理解生物识别安全是保护数字身份的基础！

来源：中国科学院信息工程研究所`;

const ARTICLE_119 = `一、小白剧场

小白：东哥，什么是脑机接口(BCI)安全？
大东：脑机接口是连接大脑和外部设备的通信系统，可以读取脑信号或向大脑发送信号。BCI安全是保护这些系统免受攻击，确保用户大脑数据隐私和设备安全。
小白：BCI有哪些类型？
大东：BCI类型：非侵入式——脑电图(EEG)帽，安全但信号弱；半侵入式——植入颅骨下，信号较好；侵入式——植入脑组织，信号最强但风险高；消费级——游戏、健康监测；医疗级——治疗瘫痪、癫痫等；增强型——提升认知能力（尚在研究）。
小白：BCI面临哪些安全威胁？
大东：BCI安全威胁：信号窃听——截获脑电波数据；恶意刺激——向大脑发送有害信号；数据泄露——思维、情绪、意图隐私；身份盗用——伪造脑信号冒充；恶意软件——控制BCI设备；侧信道攻击——通过功耗等推断脑活动；伦理风险——思想控制和操纵。

二、大话始末

小白：东哥，BCI隐私保护有多重要？
大东：BCI隐私重要性：脑数据直接反映思维、情绪、意图；可能泄露政治倾向、性取向、健康状况；思想自由的基本权利；一旦泄露无法更改（不像密码）；需要最严格的隐私保护；可能涉及思想隐私的法律保护。
小白：如何保护BCI系统安全？
大东：BCI保护措施：信号加密——脑信号传输加密；访问控制——严格限制脑数据访问；本地处理——尽可能本地处理减少传输；异常检测——识别异常刺激模式；安全更新——固件安全更新机制；物理安全——防止设备被篡改；伦理审查——研究伦理委员会监督。
小白：BCI的伦理和法律问题？
大东：伦理法律问题：知情同意——用户理解风险；认知自由——防止思想控制；身份认同——"我还是我吗"；公平获取——避免增强技术加剧不平等；责任归属——BCI辅助行为的法律责任；监管框架——BCI产品的审批和监管；国际规范——BCI武器化禁止。
小白：BCI在医疗领域的安全考虑？
大东：医疗BCI安全：设备可靠性——生命安全相关；电磁兼容——不干扰其他医疗设备；生物相容性——长期植入不引起排异；故障安全——故障时不伤害患者；数据完整性——诊断数据准确；隐私保护——患者敏感信息；持续监测——长期安全跟踪。
小白：消费级BCI的安全现状？
大东：消费级BCI现状：安全意识不足——厂商重视功能轻视安全；标准缺失——缺乏安全标准；监管滞后——监管框架不完善；用户认知——用户不了解风险；攻击案例——已有概念验证攻击；需要行业自律和监管介入。
小白：BCI安全的未来方向？
大东：未来方向：安全架构——BCI专用安全设计；隐私计算——脑数据隐私保护技术；神经伦理——BCI伦理框架；法律法规——BCI专门立法；标准制定——安全标准和测试方法；公众教育——提高BCI安全意识；国际合作——BCI治理全球协调。
小白：神经接口安全是人机融合时代的终极挑战！
大东：没错，BCI代表了人机融合的未来，安全伦理问题最为敏感。小白，BCI安全不仅是技术问题，更是人类尊严和自由的保障！

来源：中国科学院信息工程研究所`;

const ARTICLE_120 = `一、小白剧场

小白：东哥，网络安全未来会怎么发展？
大东：网络安全正面临前所未有的变革：攻击面持续扩大——IoT、云原生、AI等新技术的普及；攻击手段智能化——AI被用于攻击；威胁行为者多样化——国家级、犯罪集团、内部人员；防御理念革新——从零信任到持续验证；技术深度融合——安全与业务深度融合。
小白：未来网络安全的主要挑战？
大东：未来挑战：量子计算威胁——现有加密体系面临颠覆；AI对抗——攻防双方的AI军备竞赛；供应链安全——全球化供应链的复杂风险；人才短缺——安全专业人才严重不足；法规合规——全球数据保护法规趋严；技能差距——新技术安全知识滞后。
小白：网络安全技术发展趋势？
大东：技术趋势：AI驱动安全——智能检测和响应；零信任架构——永不信任，始终验证；安全左移——开发阶段嵌入安全；隐私增强技术——数据可用不可见；量子安全密码——抵抗量子攻击；自动化响应——SOAR减少人工干预；威胁情报共享——协同防御。

二、大话始末

小白：东哥，网络安全行业会有什么变化？
大东：行业变化：安全即服务——云原生安全服务普及；平台化整合——统一安全平台取代点方案；安全运营中心化——SOC成为标配；保险化——网络安全保险发展；量化风险——安全投入ROI可衡量；人才多元化——需要复合型人才；生态协作——厂商、用户、政府协作。
小白：个人如何适应未来安全挑战？
大东：个人适应建议：持续学习——跟踪新技术和威胁；安全意识——安全习惯养成；隐私保护——了解数据价值；多因素认证——保护关键账户；备份习惯——重要数据备份；批判思维——识别虚假信息；技能提升——学习基础安全知识；参与社区——分享和学习。
小白：国家网络安全战略方向？
大东：国家战略方向：关键基础设施保护——能源、金融、交通等；供应链安全——国产化和技术自主可控；数据主权——数据本地化和管理；人才培养——网络安全教育普及；国际合作——网络空间命运共同体；法规完善——适应新技术发展；军民融合——国防和民用协同。
小白：网络安全与新兴技术融合？
大东：技术融合：AI+安全——智能攻防；区块链+安全——可信存证；5G/6G+安全——新一代通信安全；IoT+安全——万物互联安全；云原生+安全——弹性安全架构；边缘计算+安全——分布式安全；量子+安全——量子密码和PQC；生物技术+安全——DNA数据保护。
小白：网络安全的终极目标是什么？
大东：终极目标：韧性——遭受攻击后快速恢复；可信——建立可信数字环境；隐私——保护个人数字权利；安全——防御各类网络威胁；可持续——安全能力持续演进；人本——以人为中心的安全设计；共赢——构建网络空间命运共同体。
小白：网络安全是数字时代的生存技能！
大东：没错，未来所有组织和个人都深度依赖数字世界，网络安全是生存和发展的基础。小白，保持学习，保持警惕，共同建设更安全的数字未来！

来源：中国科学院信息工程研究所`;

function createInitialSetup(
  computing: number,
  funds: number,
  information: number,
  security: number,
  areas: AreaType[],
  markers: Record<AreaType, number>
): InitialSetup {
  return {
    playerResources: { computing, funds, information },
    securityLevel: security,
    controlledAreas: areas,
    areaMarkers: markers,
    handCards: []
  };
}

function createEnemyConfig(
  name: string,
  type: EnemyConfig['type'],
  baseDifficulty: number,
  resourceBonus: number,
  attackPattern: EnemyConfig['attackPattern'],
  specialAbilities: EnemyConfig['specialAbilities'] = []
): EnemyConfig {
  return {
    name,
    type,
    baseDifficulty,
    attackPattern,
    specialAbilities,
    resourceBonus
  };
}

