    articleContent: `小白：东哥，我最近看到了一个新闻，网络攻击影响到了实体生产。
大东：没错，网络攻击除了具备形式多变的特点外，它还无处不在。让我想起了最最经典的一次网络攻击——震网病毒。
小白：是的，都是利用网络攻击对实体运转产生了影响。
大东：震网病毒通过加快离心机损坏的速度从而阻止了核计划。还有某品牌汽车受到网络攻击影响停工的案例。
小白：汽车也会遭受网络攻击？
大东：2022年2月，该汽车品牌的主要供应商遭到网络攻击，导致零部件供应管理系统停止运行。该品牌将2022财年的年度产量目标从此前的900万辆削减到了850万辆。
小白：看来网络攻击真的是"兵不刃血"。
大东：类似案例还有很多。2000年澳大利亚污水处理厂故障事件，前工程师蓄意报复导致100万公升污水未经处理直接排入自然水系。2006年美国阿拉巴马州核电站受到网络攻击，反应堆再循环泵和冷凝除矿控制器工作失灵。这些都是工控安全事件。`,
