小白：Conti是谁来着？
大东：最早，在2019年该勒索软件家族就被发现，它背后的攻击组织以RaaS（勒索软件即服务）形式在地下论坛运营。该勒索软件主要利用其他恶意软件、钓鱼邮件、漏洞利用和远程桌面协议（RDP）暴力破解进行传播。
小白：那本次台达电子被Conti勒索的事件严重吗？
大东：据当地媒体报道，有记者已获得一份内部事件报告副本，报告数据显示，台达电子的12000多台计算机和1500多台服务器已被攻击者加密。攻击者向台达电子索要1500万美元的赎金。
