    articleTitle: '第130篇：ChatGPT的Chat安全吗？丨大东话安全',
    articleContent: `小白：我在看ChatGPT的文章，最近这玩意火出圈了。
大东：ChatGPT对现代人的生活方式的改变堪称具有里程碑意义。ChatGPT可以在网络安全领域有很多应用，比如辅助代码审计、威胁分析等，还有可能生成网络攻击脚本、钓鱼邮件等。
小白：确实，写代码一直被认为是一种高端的技术，但是ChatGPT的横空出世，无异于降维打击。
大东：其实每一次AI技术的突飞猛进，都会引起一番关于"奇点是否已经来临"的大讨论。ChatGPT与维基百科的信息输入方式有相似之处，前者是开放数据+用户修正投喂，不断强化学习能力。
小白：这样看起来，确实如此。可别把咱ChatGPT给喂坏了。
大东：是的，更进一步可以假定AI智能体投喂污染ChatGPT。引用"八个打"的说法，安全人员有时需要打地鼠、打苍蝇，自然也会需要打游击、打太极。由于黑客和灰产有不同层级的目的，所以如果ChatGPT经常会有恶意投喂，可能会造成互联网大范围的知识体系级意识攻击隐患。
小白：意识攻击？这太可怕了，看来AIGC是双刃剑啊！`,
