    articleTitle: '第131篇：电商APP后门风波：你的隐私安全吗？丨大东话安全',
    articleContent: `小白：东哥，现在网购真是太方便、划算了。
大东：小白，说起电商APP来，最近有一个安全研究团队发表了一篇报告，说这个APP疑似能提权控制手机，从而绕过隐私合规监管，收集用户的各种信息。
小白：什么？真的假的？哪些信息都被收集了？
大东：报告里说，其收集的用户隐私信息包括但不限于社交媒体账户资料、位置信息、WiFi信息、基站信息甚至是路由器信息等等。
小白：天哪，那不是相当于把我的所有网络活动都暴露给他们了吗？
大东：这个要追溯到2022年，Google的Project Zero发布了一个在野漏洞利用的分析，警告攻击者已经瞄准各手机厂商的OEM代码部分，挖掘出其中的脆弱点和漏洞，组合出了一套完整的提权攻击Exploit。
小白：这可太精妙了，一环扣一环啊！
大东：该厂商持续挖掘新的安卓OEM相关漏洞，在其公开发布的App中实现对目前市场主流手机系统的漏洞攻击。OEM漏洞攻击是一个很典型的案例，与AOSP、上游Kernel的漏洞挖掘难度相比，手机厂商OEM代码部分的漏洞挖掘难度要低很多，且利用通常也相当稳定。`,
