    name: 'AI换脸——眼见就一定为实吗？',
    subtitle: '深度伪造与电信诈骗',
    articleTitle: '第135篇：AI换脸——眼见就一定为实吗？丨大东话安全',
    articleContent: `小白：短视频网站发布了AI换脸的功能，感觉挺有趣的，现在AI换脸再加上AI合成的语言更没人知道我是谁了。
大东：AI换脸和AI换声技术的确提高了生产力。在电影和电视剧中，可以利用AI换脸技术实现对角色面部的替换，这为电影制作和娱乐产业带来了更大的创作自由度和表现力。
小白：感觉AI换脸视频的主要功能还是应用在娱乐上。
大东：这个技术会对影视行业、广告行业及其他娱乐行业产生很大影响。当然新技术带来好处的同时，也会有一些不法分子想要钻空子为自己牟利。
小白：这个我还真遇到过，之前偶然刷到一个直播间正在带货，主播的面容还感觉在哪里见过，后来发现只是使用了AI实时换脸技术的普通主播。
大东：最近包头警方公布了一起典型的利用人工智能进行电信诈骗的案例，福州市的郭先生在短短的10分钟内被骗走了430万元。犯罪分子通过智能AI换脸技术，佯装成好友对他实施了诈骗。
小白：眼见都不一定为实了。犯罪分子行动太快了，一看就是经过精心设计的。
大东：新技术都是双刃剑，它可以成为娱乐、生产的工具，也可以成为侵权违法的工具。关键是看新技术掌握在谁手里。`,
